<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Authentication\Application\SessionManager;
use Civi\Lughauth\Features\OAuth\Session\Domain\SessionInfo;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\SessionStoreGateway;

final class SessionManagerUnitTest extends TestCase
{
    public function test_remove_session_delegates_to_store(): void
    {
        $deleted = null;
        $store = $this->makeStore(
            onDelete: function (string $state) use (&$deleted) {
                $deleted = $state;
            }
        );

        $manager = new SessionManager($store);
        $manager->removeSession('code-123');

        $this->assertSame('code-123', $deleted);
    }

    public function test_load_session_delegates_to_store(): void
    {
        $info = new SessionInfo('csid', true, 'iss', 'u', 'c');
        $store = $this->makeStore(session: $info);

        $manager = new SessionManager($store);
        $result = $manager->loadSession('code-abc', 'nonce', 'state');

        $this->assertSame($info, $result);
    }

    public function test_load_session_returns_null_when_not_found(): void
    {
        $manager = new SessionManager($this->makeStore(session: null));
        $this->assertNull($manager->loadSession('x', 'n', 's'));
    }

    private function makeStore(?SessionInfo $session = null, ?callable $onDelete = null): SessionStoreGateway
    {
        return new class ($session, $onDelete) implements SessionStoreGateway {
            public function __construct(private ?SessionInfo $session, private $onDelete)
            {
            }
            public function loadSession(string $state): ?SessionInfo
            {
                return $this->session;
            }
            public function findActiveSessionIdByCsid(string $csid): ?string
            {
                return null;
            }
            public function saveSession(string $s, \Civi\Lughauth\Features\OAuth\Client\Domain\ClientData $c, string $iss, \Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState $k, \Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult $v, string $csid, \DateInterval $exp): void
            {
            }
            public function updateSession(string $n, string $o): void
            {
            }
            public function deleteSession(string $state): void
            {
                if ($this->onDelete) {
                    ($this->onDelete)($state);
                }
            }
            public function purgeExpired(): void
            {
            }
        };
    }
}
